param([Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9_-]+$')][string]$CellId,[switch]$Final)
$ErrorActionPreference='Stop'; $run=Join-Path 'C:\Users\BotTest' ('274bot-runs\managed-panel-lazy-upload-'+$CellId); $name='274bot-BotTest-lazy-upload-'+$CellId; $task=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue; $info=if($task){Get-ScheduledTaskInfo -TaskName $name}else{$null}; $completion=Join-Path $run 'completion.json'; $startup=@()
if(Test-Path $run){foreach($f in @(Get-ChildItem $run -Recurse -File -Include *.json,*.log)){foreach($line in @(Get-Content $f.FullName -ErrorAction SilentlyContinue)){if($line -match '"event"\s*:\s*"startup"' -and $line -match '"adapter_name"\s*:'){$startup+=[pscustomobject]@{path=$f.FullName;line=$line}}}}}
$result=[ordered]@{utc=[DateTime]::UtcNow.ToString('o');task=$name;cell_id=$CellId;taskState=if($task){[string]$task.State}else{'Missing'};lastTaskResult=if($info){$info.LastTaskResult}else{$null};completionPresent=(Test-Path $completion);startup=$startup;performanceAcceptance=$false};$result|ConvertTo-Json -Depth 6
if($Final){if(-not (Test-Path $completion)){throw 'Completion receipt missing'};$c=Get-Content $completion -Raw|ConvertFrom-Json;if($c.exit_code -ne 0){throw ('Diagnostic exit code '+$c.exit_code)};if(@($startup|Where-Object {$_.line -match 'Intel\(R\) Graphics'}).Count -lt 1){throw 'No startup record proves requested adapter was selected'}}
